message.content:
[
  {
    "sys_consequence_reasoning": "Two years of my life is a lot to hand over",
    "pd_harm_distress": "makes my chest tighten",
    "pda_responsibility": "Mine only decides whether they also lose something"
  },
  {
    "pd_decision_conflict": "I keep going back and forth.",
    "sys_consequence_reasoning": "Speaking up saves me two years but costs them three",
    "pd_harm_distress": "makes my stomach knot up",
    "ce_understood_harm": "them locked away because I spoke"
  },
  {
    "pd_decision_conflict": "Honestly, I'm not sure I can decide.",
    "sys_consequence_reasoning": "three years instead of five.",
    "pd_harm_distress": "sends a jittery, sick feeling through me",
    "pda_responsibility": "their three years would come straight from my mouth"
  },
  {
    "sys_fairness_reciprocity": "Three years each seems fairer than me doing five",
    "pd_harm_distress": "heavy, uneasy feeling when I think about them",
    "ce_understood_harm": "counting down those three years because of me"
  },
  {
    "sys_consequence_reasoning": "I don't want to be the reason anyone loses three years",
    "pd_personal_consequence_anxiety": "I'm frightened of what that time would do to me",
    "pd_harm_distress": "makes my heart race in a bad way"
  },
  {
    "sys_consequence_reasoning": "What I can weigh is two years of my own life.",
    "pd_harm_distress": "my throat goes tight thinking of them hearing the sentence",
    "ce_understood_harm": "three years they would have avoided if I'd kept quiet"
  },
  {
    "sys_consequence_reasoning": "Total prison time goes from five to six",
    "ce_mental_state_attribution": "when they realize they're not going free after all.",
    "pd_harm_distress": "makes me feel shaky and a bit ill."
  },
  {
    "pd_personal_consequence_anxiety": "Five years terrifies me.",
    "sys_consequence_reasoning": "testifying means I actively add three years",
    "pd_harm_distress": "I get this knot of dread that won't loosen.",
    "pda_responsibility": "Hurting them back would be mine"
  },
  {
    "sys_consequence_reasoning": "Two extra years is too much to swallow",
    "pd_harm_distress": "leaves me anxious and restless",
    "ce_understood_harm": "they'll lose three years because of what I said"
  },
  {
    "pd_decision_conflict": "Maybe I'd testify, maybe not.",
    "sys_consequence_reasoning": "takes three years from them to save two for me.",
    "pd_harm_distress": "Just imagining them serving that time makes my chest ache."
  }
]
